import { FC } from 'react';
import { useTranslation } from 'react-i18next';

import { Button, Drawer, DrawerProps, Flex, Form, Select } from 'antd';
import cn from 'classnames';

import { ESourceRelationStatuses } from 'entities/Offer';
import { EFilters, useFilters } from 'features/Filters';
import { useCommonSlice, useDisableBodyScroll } from 'shared/hooks';

import styles from './MyOffersExtendedFilters.module.scss';

interface IMyOffersExtendedFiltersProps extends DrawerProps {}

export const MyOffersExtendedFilters: FC<IMyOffersExtendedFiltersProps> = ({ className, onClose, open, ...props }) => {
	const { t } = useTranslation();
	const {
		sourcesOptions,
		brandsOptions,
		offersOptions,
		sourcesIsFetching,
		brandsIsFetching,
		offersIsFetching,
		onFilterChange,
		getALLFilterValues,
		clearFilters,
	} = useFilters();
	const {
		categoryOptions,
		trafficTypeOptions,
		tagsOptions,
		trans: { relationStatuses },
	} = useCommonSlice();

	useDisableBodyScroll(!!open);

	return (
		<Drawer
			{...props}
			open={open}
			onClose={onClose}
			width={450}
			title={t('Фильтры')}
			className={cn(className, styles.brandExtendedFilters)}>
			<Flex vertical gap={16}>
				<Form.Item label={t('Площадка')} layout="vertical">
					<Select
						mode="multiple"
						maxTagCount="responsive"
						onChange={(value) => onFilterChange(EFilters.SOURCE, value)}
						value={sourcesIsFetching ? null : getALLFilterValues(EFilters.SOURCE)}
						options={sourcesOptions}
						loading={sourcesIsFetching}
						disabled={sourcesIsFetching}
						showSearch
						optionFilterProp="label"
						placeholder={t('Выбрать площадку')}
						allowClear
						getPopupContainer={(trigger) => trigger.parentElement}
					/>
				</Form.Item>

				<Form.Item label={t('Рекламодатель')} layout="vertical">
					<Select
						mode="multiple"
						maxTagCount="responsive"
						onChange={(value) => onFilterChange(EFilters.BRAND, value)}
						value={brandsIsFetching ? null : getALLFilterValues(EFilters.BRAND)}
						options={brandsOptions}
						loading={brandsIsFetching}
						disabled={brandsIsFetching}
						showSearch
						optionFilterProp="label"
						placeholder={t('Выбрать рекламодателя')}
						allowClear
						getPopupContainer={(trigger) => trigger.parentElement}
					/>
				</Form.Item>

				<Form.Item label={t('Оффер')} layout="vertical">
					<Select
						mode="multiple"
						maxTagCount="responsive"
						onChange={(value) => onFilterChange(EFilters.OFFER, value)}
						value={offersIsFetching ? null : getALLFilterValues(EFilters.OFFER)}
						options={offersOptions}
						loading={offersIsFetching}
						disabled={offersIsFetching}
						showSearch
						optionFilterProp="label"
						placeholder={t('Выбрать оффер')}
						allowClear
						getPopupContainer={(trigger) => trigger.parentElement}
					/>
				</Form.Item>

				<Form.Item label={t('Категория')} layout="vertical">
					<Select
						mode="multiple"
						maxTagCount="responsive"
						onChange={(value) => onFilterChange(EFilters.CATEGORY, value)}
						value={getALLFilterValues(EFilters.CATEGORY)}
						options={categoryOptions}
						showSearch
						optionFilterProp="label"
						placeholder={t('Выбрать категорию')}
						allowClear
						getPopupContainer={(trigger) => trigger.parentElement}
					/>
				</Form.Item>

				<Form.Item label={t('Тип траффика')} layout="vertical">
					<Select
						mode="multiple"
						maxTagCount="responsive"
						onChange={(value) => onFilterChange(EFilters.TRAFFIK, value)}
						value={getALLFilterValues(EFilters.TRAFFIK)}
						options={trafficTypeOptions}
						showSearch
						optionFilterProp="label"
						placeholder={t('Выбрать тип траффика')}
						allowClear
						getPopupContainer={(trigger) => trigger.parentElement}
					/>
				</Form.Item>

				<Form.Item label={t('Статус')} layout="vertical">
					<Select
						mode="multiple"
						maxTagCount="responsive"
						onChange={(value) => onFilterChange(EFilters.STATUS, value)}
						value={getALLFilterValues(EFilters.STATUS)}
						options={Object.entries(relationStatuses)
							.filter(([key]) => key !== ESourceRelationStatuses.NOT_JOINED && key !== ESourceRelationStatuses.DISABLED)
							.map(([value, label]) => ({ label, value }))}
						showSearch
						optionFilterProp="label"
						placeholder={t('Выбрать статус')}
						allowClear
						getPopupContainer={(trigger) => trigger.parentElement}
					/>
				</Form.Item>

				<Form.Item label={t('Теги')} layout="vertical">
					<Select
						mode="multiple"
						maxTagCount="responsive"
						onChange={(value) => onFilterChange(EFilters.TAG, value)}
						value={getALLFilterValues(EFilters.TAG)}
						options={tagsOptions}
						showSearch
						optionFilterProp="label"
						placeholder={t('Выбрать значение')}
						allowClear
						getPopupContainer={(trigger) => trigger.parentElement}
					/>
				</Form.Item>

				<Flex justify="space-between" className={styles.buttons}>
					<Button
						onClick={(e) => {
							clearFilters();
							onClose?.(e);
						}}>
						{t('Сбросить фильтры')}
					</Button>
					<Button type="primary" onClick={onClose}>
						{t('Применить')}
					</Button>
				</Flex>
			</Flex>
		</Drawer>
	);
};
