import { FC, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useSearchParams } from 'react-router-dom';

import { Flex, FlexProps } from 'antd';

import { OfferCard, useGetOfferListQuery } from 'entities/Offer';
import { MyOffersFilters } from 'features/Filters';
import { Pagination } from 'features/Pagination';
import { Sort } from 'features/Sort';
import { EmptyState, ListTopbar, OpenAllSwitch, OverlayLoader } from 'shared/ui';
import { SORT_ITEMS } from 'widgets/OffersList';

interface IOffersListProps extends FlexProps {}

export const OffersList: FC<Omit<IOffersListProps, 'children'>> = ({ ...props }) => {
	const { t } = useTranslation();
	const [allIsOpened, setAllIsOpened] = useState(!!localStorage.getItem('allOffersIsOpened'));

	const [searchParams] = useSearchParams();
	const { data, isFetching } = useGetOfferListQuery(searchParams.toString());
	const hasData = !!data?.results?.length;

	return (
		<Flex {...props} vertical gap={16}>
			{isFetching && <OverlayLoader />}

			<MyOffersFilters />

			{!hasData && !isFetching && <EmptyState title={t('Пока нет ваших офферов')} />}

			{hasData && (
				<>
					<ListTopbar
						leftComponent={<Sort sortItems={SORT_ITEMS} />}
						rightComponent={
							<OpenAllSwitch allIsOpened={allIsOpened} setAllIsOpened={setAllIsOpened} storageKey="allOffersIsOpened" />
						}
					/>

					<Flex vertical gap={12}>
						{data.results?.map((offer) => (
							<OfferCard key={offer.uuid} offer={offer} allIsOpened={allIsOpened} isMyOffers />
						))}
					</Flex>

					<Pagination count={data?.count || 1} nouns={[t('рекламодатель'), t('рекламодателя'), t('рекламодателей')]} />
				</>
			)}
		</Flex>
	);
};
